package com.hbm.entity.logic;
import com.hbm.energy.EnergyHandler;import com.hbm.entity.LegacyTrackingRange;import com.hbm.missile.completion.*;import java.math.BigInteger;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.syncher.SynchedEntityData;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.neoforged.neoforge.capabilities.Capabilities;
/** Source sustained logic EMP, distinct from an expanding visual EMP ring. */
public final class EntityEMP extends Entity implements LegacyTrackingRange {
 private List<BlockPos> machines;public static final int LIFE=10*60*20;public EntityEMP(EntityType<?> type,Level level){super(type,level);}public EntityEMP(Level level){this(MissileContent.EMP.get(),level);}@Override public int legacyTrackingRange(){return 1000;}@Override protected void defineSynchedData(SynchedEntityData.Builder builder){}
 @Override public void tick(){if(level() instanceof ServerLevel server){if(machines==null)allocate(server);else for(var pos:machines)shock(server,pos);if(tickCount>LIFE)discard();}}
 private void allocate(ServerLevel server){machines=new ArrayList<>();int x=(int)getX(),y=(int)getY(),z=(int)getZ();for(int cx=Math.floorDiv(x-100,16);cx<=Math.floorDiv(x+100,16);cx++)for(int cz=Math.floorDiv(z-100,16);cz<=Math.floorDiv(z+100,16);cz++){var chunk=server.getChunk(cx,cz);for(var entry:chunk.getBlockEntities().entrySet()){var pos=entry.getKey();int dx=pos.getX()-x,dy=pos.getY()-y,dz=pos.getZ()-z;if(dx*dx+dy*dy+dz*dz>10000)continue;if(entry.getValue() instanceof EnergyHandler||external(server,pos))machines.add(pos.immutable());}}machines.sort(Comparator.<BlockPos>comparingInt(BlockPos::getX).thenComparingInt(BlockPos::getY).thenComparingInt(BlockPos::getZ));}
 private boolean external(ServerLevel level,BlockPos pos){for(var side:Direction.values()){var storage=level.getCapability(Capabilities.EnergyStorage.BLOCK,pos,side);if(storage!=null&&storage.canExtract())return true;}return false;}
 private void shock(ServerLevel level,BlockPos pos){if(!level.hasChunkAt(pos))return;boolean affected=false;var tile=level.getBlockEntity(pos);if(tile instanceof EnergyHandler energy){energy.setPowerExact(BigInteger.ZERO);affected=true;}for(var side:new Direction[]{Direction.UP,Direction.DOWN,Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST}){var storage=level.getCapability(Capabilities.EnergyStorage.BLOCK,pos,side);if(storage!=null&&storage.canExtract()){storage.extractEnergy(storage.getEnergyStored(),false);affected=true;}}if(affected&&random.nextInt(20)==0)EmpMachineSparks.send(level,position(),pos);}
 /** Source deliberately does not serialize the cache or lifetime; on reload it reallocates current receivers. */
 @Override protected void readAdditionalSaveData(CompoundTag tag){}@Override protected void addAdditionalSaveData(CompoundTag tag){}
}
